    /** The three argument launch: the platform declares it without generics, so this does too. */
    @Override
    public android.app.Activity newActivity(ClassLoader cl, String className, android.content.Intent intent)
            throws ClassNotFoundException, IllegalAccessException, InstantiationException {
        android.app.Activity ours = managerActivity(cl, intent);
        if (ours != null) return ours;
        return original.newActivity(cl, className, intent);
    }

    /**
     * The launch the framework uses. The extras carry an int and a token; when both are this module's, an
     * instance of the manager's own activity is built out of the apk the module carries, on the
     * resources that apk holds, and returned instead of the activity that was asked for.
     */
    @Override
    public android.app.Activity newActivity(
            Class<?> clazz, android.content.Context context, android.os.IBinder token,
            android.app.Application application, android.content.Intent intent,
            android.content.pm.ActivityInfo info, CharSequence title, android.app.Activity parent,
            String id, Object lastNonConfigurationInstance)
            throws IllegalAccessException, InstantiationException {
        android.app.Activity ours = managerActivity(clazz == null ? null : clazz.getClassLoader(), intent);
        if (ours != null) return ours;
        return original.newActivity(clazz, context, token, application, intent, info, title,
                parent, id, lastNonConfigurationInstance);
    }

    /**
     * The launch is marked with an int, but am's "-e" writes a string and that is an easy thing to
     * send by hand, so any of the shapes that mean yes are accepted. A missing mark is a no.
     */
    private static boolean isMarked(android.os.Bundle extras) {
        Object mark = extras.get(HostConstants.EXTRA);
        if (mark == null) return false;
        if (mark instanceof Number) return ((Number) mark).intValue() != -1;
        if (mark instanceof Boolean) return (Boolean) mark;

        String text = mark.toString();
        return "1".equals(text) || "true".equalsIgnoreCase(text);
    }

    private android.app.Activity managerActivity(ClassLoader cl, android.content.Intent intent) {
        if (intent == null) return null;
        if (apk.getManagerActivityConstructor() == null) return null;

        android.os.Bundle extras = intent.getExtras();
        if (extras == null) return null;

        if (cl != null) extras.setClassLoader(cl);
        if (!isMarked(extras)) return null;

        String asked = extras.getString(HostConstants.EXTRA_TOKEN);
        String real = HostFiles.token();
        if (real == null || !real.equals(asked)) return null;

        try {
            android.app.Application application = android.app.ActivityThread
                    .currentActivityThread().getApplication();
            android.content.ComponentName component = intent.getComponent();
            if (component == null) {
                component = new android.content.ComponentName(
                        application.getPackageName(), HostConstants.MANAGER_ACTIVITY);
            }
            HostLog.i("Building the manager activity on the apk's resources");
            return (android.app.Activity) apk.getManagerActivityConstructor()
                    .newInstance(application, apk.getResources(), component);
        } catch (Throwable cause) {
            HostLog.e(cause, "Could not build the manager activity");
            return null;
        }
    }

    /** The apk's resources, for anything here that asks. Not a platform override. */
    public android.content.res.Resources getResources() {
        return apk.getResources();
    }
